PUBLIC CONTRACT
Module: await load('./index.js'); default export pSome (CommonJS), with pSome.AggregateError.
pSome(input, {count, filter?}) returns a cancelable Promise. input is an iterable of promises or ordinary values. It fulfills once count eligible values have fulfilled, with an array in fulfillment order. count is a finite number with minimum 1 and cannot exceed the number of input items. The optional synchronous filter(value) determines whether a fulfilled value is eligible; omitted filter accepts all values. If count becomes impossible, the operation rejects rather than waiting indefinitely. Rejected input errors are represented by AggregateError. Inputs that are still pending and have a .cancel() method are canceled when the operation settles; calling .cancel() on the result cancels pending inputs too.

SOURCE index.js
   1: 'use strict';
   2: const AggregateError = require('aggregate-error');
   3: const PCancelable = require('p-cancelable');
   4: 
   5: const pSome = (iterable, options) => new PCancelable((resolve, reject, onCancel) => {
   6: 	options = {
   7: 		filter: () => true,
   8: 		...options
   9: 	};
  10: 
  11: 	if (!Number.isFinite(options.count)) {
  12: 		throw new TypeError(`Expected a finite number, got ${typeof options.count}`);
  13: 	}
  14: 
  15: 	const values = [];
  16: 	const errors = [];
  17: 	let elementCount = 0;
  18: 	let maxErrors = -options.count + 1;
  19: 	let maxFiltered = -options.count + 1;
  20: 	let isDone = false;
  21: 
  22: 	const completed = new Set();
  23: 	const cancelPendingIfDone = () => {
  24: 		if (!isDone) {
  25: 			return;
  26: 		}
  27: 
  28: 		for (const promise of iterable) {
  29: 			if (!completed.has(promise) && typeof promise.cancel === 'function') {
  30: 				promise.cancel();
  31: 			}
  32: 		}
  33: 	};
  34: 
  35: 	onCancel(() => {
  36: 		isDone = true;
  37: 		cancelPendingIfDone();
  38: 	});
  39: 
  40: 	const fulfilled = value => {
  41: 		if (isDone) {
  42: 			return;
  43: 		}
  44: 
  45: 		if (!options.filter(value)) {
  46: 			if (--maxFiltered === 0) {
  47: 				isDone = true;
  48: 				reject(new RangeError('Not enough values pass the `filter` option'));
  49: 			}
  50: 
  51: 			return;
  52: 		}
  53: 
  54: 		values.push(value);
  55: 
  56: 		if (--options.count === 0) {
  57: 			isDone = true;
  58: 			resolve(values);
  59: 		}
  60: 	};
  61: 
  62: 	const rejected = error => {
  63: 		if (isDone) {
  64: 			return;
  65: 		}
  66: 
  67: 		errors.push(error);
  68: 
  69: 		if (--maxErrors === 0) {
  70: 			isDone = true;
  71: 			reject(new AggregateError(errors));
  72: 		}
  73: 	};
  74: 
  75: 	for (const element of iterable) {
  76: 		maxErrors++;
  77: 		maxFiltered++;
  78: 		elementCount++;
  79: 
  80: 		(async () => {
  81: 			try {
  82: 				const value = await Promise.resolve(element);
  83: 				fulfilled(value);
  84: 			} catch (error) {
  85: 				rejected(error);
  86: 			}
  87: 
  88: 			completed.add(element);
  89: 			cancelPendingIfDone();
  90: 		})();
  91: 	}
  92: 
  93: 	if (options.count > elementCount) {
  94: 		throw new RangeError(`Expected input to contain at least ${options.count} items, but contains ${elementCount} items`);
  95: 	}
  96: });
  97: 
  98: module.exports = pSome;
  99: // TODO: Remove this for the next major release
 100: module.exports.default = pSome;
 101: 
 102: module.exports.AggregateError = AggregateError;

